# 範例：整理購物清單
import json
from datetime import date


class Item:
    """一項商品：名稱、單價、數量。"""

    def __init__(self, name, price, qty=1):
        self.name = name
        self.price = price
        self.qty = qty

    def total(self):
        return self.price * self.qty


def load(path):
    with open(path, encoding="utf-8") as f:
        data = json.load(f)
    return [Item(**row) for row in data["items"]]


def summary(items):
    lines = []
    for i, item in enumerate(items, start=1):
        lines.append(f"{i:>2}. {item.name:<8} {item.qty} x {item.price} = {item.total()}")
    total = sum(item.total() for item in items)
    lines.append("-" * 32)
    lines.append(f"合計 {total} 元（{date.today()}）")
    return "\n".join(lines)


if __name__ == "__main__":
    items = [Item("紙杯", 3, 50), Item("吸管", 1, 100), Item("湯匙", 2, 30)]
    print(summary(items))
    for n in range(3):
        if n % 2 == 0:
            print("偶數", n)
        else:
            print("奇數", n, None, True)
